static void tiles_editable(struct Dash *d,int off);
static void ui_close(struct Dash *d)
{tiles_editable(d,0);if(d->thumbs){ah_thumbs_free(d->thumbs);d->thumbs=NULL;}if(d->window)CloseWindow(d->window);if(d->gadgets)FreeGadgets(d->gadgets);if(d->visual)FreeVisualInfo(d->visual);if(d->screen)UnlockPubScreen(NULL,d->screen);if(d->font)CloseFont(d->font);d->window=NULL;d->gadgets=NULL;d->visual=NULL;d->screen=NULL;d->font=NULL;if(GfxBase)CloseLibrary((struct Library *)GfxBase);if(GadToolsBase)CloseLibrary(GadToolsBase);if(IntuitionBase)CloseLibrary((struct Library *)IntuitionBase);GfxBase=NULL;GadToolsBase=NULL;IntuitionBase=NULL;}
static void tiles_editable(struct Dash *d,int off)
{if(!d->window||!d->cells||off==tiles_off)return;
 if(off){tiles_at=(int)RemoveGList(d->window,d->tiles[0],(LONG)d->cells);if(tiles_at<0)return;tiles_off=1;}
 else{AddGList(d->window,d->tiles[0],(UWORD)tiles_at,(LONG)d->cells,NULL);RefreshGList(d->tiles[0],d->window,NULL,(LONG)d->cells);tiles_off=0;}}
static int cell_at(struct Dash *d,int x,int y)
{int i;for(i=0;i<(int)d->cells;++i)if(x>=d->x[i]&&x<d->x[i]+d->width[i]&&y>=d->y[i]&&y<d->y[i]+d->height[i])return i;return -1;}
static int cell_index(struct Dash *d,int cell){return (int)(d->row_offset*d->layout.columns)+cell;}
static void tile_text(struct RastPort *rp,int x,int y,const char *text,int max)
{int n;text=ah_tx(text);n=strlen(text);if(n>max)n=max;if(n>0){Move(rp,x,y);Text(rp,(STRPTR)text,n);}}
static void invalidate(struct Dash *d)
{memset(d->drawn_valid,0,sizeof(d->drawn_valid));d->shown_status[0]=d->shown_hint[0]=1;d->shown_status[1]=d->shown_hint[1]=0;d->shown_title=d->shown_control=d->shown_edit=NULL;d->shown_flags=-1;}
/* Builds each visible cell's text and redraws a cell only when what it shows
 * changed (or the window was damaged). Camera tiles always redraw. */
