   if(ah_sparks_range(&d->sparks,(unsigned int)i,&lo,&hi)){ah_sparks_text(lo,a);ah_sparks_text(hi,b);sprintf(range,"%s-%s",a,b);if((int)strlen(range)*8+40<gw){gw-=(int)strlen(range)*8+6;SetAPen(rp,1);tile_text(rp,gx+gw+6,gy+gh-2,range,(int)strlen(range));}}
