  if(gauge_shown){int gx=x+42,gy=y+d->height[cell]-8,gw=d->width[cell]-50;SetAPen(rp,1);RectFill(rp,gx,gy,gx+gw,gy+4);if(gauge_shown==2){SetAPen(rp,3);if(level)RectFill(rp,gx+1,gy+1,gx+(gw-2)*level/100,gy+3);}else{SetAPen(rp,0);RectFill(rp,gx+1,gy+1,gx+gw-1,gy+3);}}
