static int confirm_device_action_mode(struct Dash *d,const char *action,int selftest)
{struct NDPanelField fields[3];struct NDPanel *p;static const char *buttons[]={"Cancel","Confirm"};int event,ok=0;fields[0].label="Device";fields[0].value=d->layout.tiles[d->selected].label;fields[0].limit=0;fields[1].label="Entity";fields[1].value=d->layout.tiles[d->selected].entity;fields[1].limit=0;fields[2].label="Action";fields[2].value=(char *)action;fields[2].limit=0;p=nd_panel_open("Confirm real door action",fields,3,buttons,2);if(!p)return 0;for(;;){event=nd_panel_event(p);if(selftest)event=selftest==1 ? 100:101;if(event==-1||event==100)break;if(event==101){ok=1;break;}nd_panel_wait(p,0,50);}nd_panel_close(p);return ok;}
